package runtimestore

import (
	"os"
	"path/filepath"
	"testing"
)

// Ownership requires both the exact generated bytes and the independently
// selected target, for Unix shell and Windows .cmd forms. Extra executable
// text and wrong targets stay foreign, beside valid positive controls.
func TestLegacyShimOwnershipIsExact(t *testing.T) {
	for _, platform := range []string{"unix", "windows"} {
		t.Run(platform, func(t *testing.T) {
			root := t.TempDir()
			target := filepath.Join(root, "runtime space ' %", "tool")
			other := filepath.Join(root, "foreign", "tool")
			render := UnixShimContent
			if platform == "windows" {
				render = WindowsShimContent
			}
			path := filepath.Join(root, "shim")
			for _, entries := range [][]string{nil, {filepath.Join(root, "bin"), filepath.Join(root, "system")}} {
				for _, tc := range []struct {
					payload string
					want    bool
				}{
					{render(target, entries), true}, {render(other, entries), false}, {render(target, entries) + "extra command\n", false},
				} {
					if err := os.WriteFile(path, []byte(tc.payload), 0o700); err != nil {
						t.Fatal(err)
					}
					if got := MatchesLegacyShim(path, platform, func(value string) bool { return value == target }); got != tc.want {
						t.Fatalf("ownership=%v want=%v for %q", got, tc.want, tc.payload)
					}
				}
			}
		})
	}
}
